edit('ui/screens/devices/BuddyBotDriveHud.kt',lambda s:s.replace('import androidx.compose.foundation.Canvas','import com.halo.app.language.uiText\nimport androidx.compose.foundation.Canvas').replace('val safety = telemetry.safetyState?.uppercase() ?: if (connectionReady) "READY" else "OFFLINE"','val safety = if (!connectionReady) "OFFLINE" else telemetry.safetyState?.uppercase() ?: "UNKNOWN"').replace('val range = telemetry.rangeMm','val range = telemetry.rangeMm.takeIf { connectionReady && telemetry.rangeValid }').replace('val obstacle = telemetry.forwardMotionBlocked || telemetry.obstacleDetected','val obstacle = connectionReady && (telemetry.forwardMotionBlocked || telemetry.obstacleDetected)').replace('                    telemetry.forwardMotionBlocked ->','                    !connectionReady -> "UNKNOWN"\n                    telemetry.forwardMotionBlocked ->').replace('                    obstacle -> HaloGlassColors.Warning','                    !connectionReady -> HaloGlassColors.TextMuted\n                    obstacle -> HaloGlassColors.Warning').replace('HudMetric("MOTORS", if (telemetry.motorsArmed) "ARMED" else "OFF", if (telemetry.motorsArmed) HaloGlassColors.Success else HaloGlassColors.TextMuted)','HudMetric("Motors", buddyBotMotorLabel(connectionReady, telemetry.motorsArmed), if (connectionReady && telemetry.motorsArmed) HaloGlassColors.Success else HaloGlassColors.TextMuted)').replace('valid = telemetry.rangeValid','valid = connectionReady && telemetry.rangeValid').replace('Text(label,','Text(uiText(label),').replace('Text(value,','Text(uiText(value),').replace('Text(text,','Text(uiText(text),'))
edit('ui/screens/settings/SkillStarterEditor.kt',lambda s:s.replace('    BackHandler(onBack = onDismiss)','    var leaving by rememberSaveable { mutableStateOf(false) }\n    var nextStarter by rememberSaveable { mutableStateOf<String?>(null) }\n    val dirty = name != suggestedName || instructions != starter.instructions\n    fun leave() { if (dirty) leaving = true else onDismiss() }\n    BackHandler(onBack = ::leave)\n    if (leaving || nextStarter != null) AlertDialog(onDismissRequest = { leaving = false; nextStarter = null },\n        title = { Text(uiText("Discard skill edits?")) }, text = { Text(uiText("These instructions have not been installed. Review them before installing, or discard this draft.")) },\n        confirmButton = { TextButton(onClick = { val next = nextStarter; nextStarter = null; leaving = false; if (next != null) { starterName = next; error = null } else onDismiss() }) { Text(uiText("Discard")) } },\n        dismissButton = { TextButton(onClick = { leaving = false; nextStarter = null }) { Text(uiText("Keep editing")) } })').replace('onClick = { starterName = option.name; error = null }','onClick = { if (option != starter && dirty) nextStarter = option.name else { starterName = option.name; error = null } }').replace('TextButton(onDismiss)','TextButton(onClick = ::leave)'))
