# Move the System Check header and controls into the same scroll as its results.
p=root/'ui/screens/settings/SystemCheckScreen.kt';s=p.read_text(encoding='utf-8')
start=s.index('    val assistantLauncher = rememberLauncherForActivityResult(');end=s.index('\n    LazyColumn(',start);launcher=s[start:end]
s=s[:start]+s[end:]
pos=s.index('    Column(\n');s=s[:pos]+launcher+'\n'+s[pos:]
a=s.index('        Spacer(Modifier.height(16.dp))');b=s.index('\n    LazyColumn(',a);header=s[a:b];s=s[:a]+s[b:]
pos=s.index('        item { ProviderDiagnosticsPanel');s=s[:pos]+'        item { Column {\n'+header+'        } }\n'+s[pos:]
s=s.replace('    var pendingSpeechAction by remember {','    var pendingSpeechAction by androidx.compose.runtime.saveable.rememberSaveable {').replace('var reflectionPreview by remember {','var reflectionPreview by androidx.compose.runtime.saveable.rememberSaveable {').replace('title = "System Check"','title = uiText("System Check")').replace('subtitle = "Diagnostic hardware & runtime probe"','subtitle = uiText("Run checks explicitly. Hardware and inference checks may need access or configuration.")')
p.write_text(s,encoding='utf-8')
# Keep authored literal strings separate from source text.
for path in ['ui/screens/devices/BuddyBotDriveHud.kt','ui/screens/settings/RuntimeScreen.kt','ui/screens/settings/SystemCheckScreen.kt','ui/screens/integrations/IntegrationsScreen.kt']:
 p=root/path;s=p.read_text(encoding='utf-8');s=re.sub(r'(?<![A-Za-z0-9_])Text\(("[^"$\\\n]+")',r'Text(uiText(\1)',s);p.write_text(s,encoding='utf-8')
